(function(){
"use strict";
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));

$("#tbtn").onclick=()=>{const c=document.documentElement.getAttribute("data-theme");
  document.documentElement.setAttribute("data-theme",c==="dark"?"light":"dark");};
const secs=$$("main section"),links=$$("#toc a:not(.sub)");
function onScroll(){const h=document.documentElement;
  $("#prog").style.width=(h.scrollTop/(h.scrollHeight-h.clientHeight)*100)+"%";
  let cur=secs[0].id;for(const s of secs)if(s.getBoundingClientRect().top<=120)cur=s.id;
  links.forEach(a=>a.classList.toggle("on",a.getAttribute("href")==="#"+cur));}
document.addEventListener("scroll",onScroll,{passive:true});onScroll();

/* ══════════════════════════════════════════════════════════════════
   实验 1 · 四个 index 与读的第三步
   ══════════════════════════════════════════════════════════════════ */
const S1={log:[],match:[0,0,0,0],commit:0,applied:0,last:null};
function maj1(){
  // Leader 自己的 matchIndex 就是 lastLogIndex
  const all=S1.match.concat([S1.log.length]).slice().sort((a,b)=>b-a);
  return all[2]; // 5 个节点里第 3 大 = 过半都达到的最大值
}
function draw1(){
  const n=S1.log.length;
  let tape="",mk="";
  if(n===0){tape='<div style="color:var(--ink-3);font-size:13px;padding:8px 0">日志为空——点「客户端写」开始</div>';}
  for(let i=1;i<=n;i++){
    let cls="cell uncommitted";
    if(i<=S1.applied)cls="cell applied"; else if(i<=S1.commit)cls="cell commit";
    tape+='<div class="'+cls+'"><div><b>'+i+'</b><br><span style="font-size:10px">x='+i+'</span></div></div>';
    let m=[];
    if(i===S1.applied)m.push('<span style="color:var(--s1)">▲app</span>');
    if(i===S1.commit)m.push('<span style="color:var(--s3)">▲cmt</span>');
    if(i===n)m.push('<span style="color:var(--warn)">▲last</span>');
    mk+='<div class="mkc">'+m.join('<br>')+'</div>';
  }
  $("#t1").innerHTML=tape; $("#m1").innerHTML=mk;
  const mx=Math.max(n,1);
  const rows=[
    ["lastLogIndex",n,"var(--warn)"],
    ["commitIndex",S1.commit,"var(--s3)"],
    ["lastApplied",S1.applied,"var(--s1)"]
  ];
  let h="";
  for(const [k,v,c] of rows){
    h+='<div class="idxrow"><div class="nm">'+k+' = <b style="color:'+c+'">'+v+'</b></div>'+
       '<div class="meter"><i style="width:'+(v/mx*100)+'%;background:'+c+'"></i></div></div>';
  }
  h+='<div class="idxrow"><div class="nm" style="color:var(--ink-3)">matchIndex[]</div>'+
     '<div style="font-family:var(--mono);font-size:12px;color:var(--ink-2)">N2='+S1.match[0]+
     '　N3='+S1.match[1]+'　N4='+S1.match[2]+'　N5='+S1.match[3]+
     '　<span style="color:var(--ink-3)">（过半达到 '+maj1()+'）</span></div></div>';
  $("#ib1").innerHTML=h;
  if(S1.last)$("#o1").innerHTML=S1.last; 
}
$("#b1w").onclick=()=>{if(S1.log.length<9){S1.log.push(1);S1.last=null;$("#o1").innerHTML="";draw1();}};
$("#b1rep").onclick=()=>{S1.match=S1.match.map(m=>Math.min(m+1,S1.log.length));S1.last=null;$("#o1").innerHTML="";draw1();};
$("#b1cm").onclick=()=>{S1.commit=Math.max(S1.commit,maj1());S1.last=null;$("#o1").innerHTML="";draw1();};
$("#b1ap").onclick=()=>{S1.applied=Math.min(S1.applied+1,S1.commit);S1.last=null;$("#o1").innerHTML="";draw1();};
$("#b1reset").onclick=()=>{S1.log=[];S1.match=[0,0,0,0];S1.commit=0;S1.applied=0;S1.last=null;$("#o1").innerHTML="";draw1();};
$("#b1read").onclick=()=>{
  const wait=$("#b1wait").checked, ri=S1.commit;
  let h='<div class="note '+(wait||S1.applied>=ri?"ok":"crit")+'" style="margin:0">';
  h+='<div class="note-h"><span class="dot" style="background:var(--'+(wait||S1.applied>=ri?"ok":"crit")+')"></span>ReadIndex 读 x</div>';
  h+='<table style="margin:8px 0 0"><thead><tr><th style="width:16%">步骤</th><th style="width:32%">做了什么</th><th>结果</th></tr></thead><tbody>';
  h+='<tr><td><strong>1</strong></td><td><code>readIndex := commitIndex</code></td><td>readIndex = <strong>'+ri+'</strong></td></tr>';
  h+='<tr><td><strong>2</strong></td><td>发一轮心跳，收过半响应</td><td><span style="color:var(--ok)">✓ 我仍是合法 Leader</span></td></tr>';
  if(wait){
    const waited=Math.max(0,ri-S1.applied);
    h+='<tr><td><strong>3</strong></td><td>等 <code>lastApplied &gt;= readIndex</code></td><td>'+
       (waited>0?'<span style="color:var(--s4)">阻塞，等 apply 追 '+waited+' 条</span>':'<span style="color:var(--ok)">已满足，无需等待</span>')+'</td></tr>';
    h+='</tbody></table>';
    S1.applied=ri;
    const v=ri===0?"（初始值，尚无写入提交）":"x = "+ri;
    h+='<p style="margin:12px 0 0">返回 <strong style="font-size:16px">'+v+'</strong>　—— 这是 index='+ri+' 处的值，'+
       '正是<u>此刻全集群已提交的最新值</u>。<strong>线性一致 ✓</strong></p>';
  }else{
    h+='<tr><td><strong style="color:var(--crit)">3</strong></td><td><span style="color:var(--crit)">跳过，直接读状态机</span></td>'+
       '<td>状态机只重放到 lastApplied = <strong>'+S1.applied+'</strong></td></tr>';
    h+='</tbody></table>';
    const v=S1.applied===0?"（初始值）":"x = "+S1.applied;
    const lost=ri-S1.applied;
    h+='<p style="margin:12px 0 0">返回 <strong style="font-size:16px">'+v+'</strong>';
    if(lost>0){
      h+='　—— 而已提交的最新值是 <strong>x = '+ri+'</strong>。<br>'+
         '<strong style="color:var(--crit)">丢了 '+lost+' 条已提交的写。</strong>客户端在写 x='+ri+' 时已经收到过「成功」，'+
         '现在读回来却是 x='+(S1.applied||0)+'——<u>线性一致性破裂</u>。<br>'+
         '<em>注意：前两步全部正确通过了。</em>确认自己是 Leader、拿到正确的提交点，都不能替代「等状态机追上来」。';
    }else{
      h+='　—— 这次恰好 <code>lastApplied == commitIndex</code>，没出事。<br>'+
         '<span style="color:var(--s4)">再多写几条、多点几次「推进 commitIndex」而少点「apply」，把窗口拉开再读一次。</span>';
    }
    h+='</p>';
  }
  h+='</div>';
  S1.last=h; draw1();
};
draw1();

/* ══════════════════════════════════════════════════════════════════
   实验 2 · no-op 的必要性
   ══════════════════════════════════════════════════════════════════ */
const S2={i:0};
function steps2(noop){
  const base=[
   {t:"任期 2：Leader N1 把 3 条写复制到了过半",
    nodes:[["N1","L",2,"1,2,3",3,3],["N2","F",2,"1,2,3",0,0],["N3","F",2,"1,2,3",0,0],["N4","F",2,"—",0,0],["N5","F",2,"—",0,0]],
    note:"N1 把 <code>x=1,2,3</code> 复制给了 N2、N3，<strong>{N1,N2,N3} 已经过半</strong>。<br>"+
         "于是 N1 把自己的 <code>commitIndex</code> 推到 3，并<strong style='color:var(--s3)'>回复客户端「x=3 写入成功」</strong>。<br>"+
         "<span style='color:var(--ink-3)'>注意 N2、N3 的 commitIndex 还是 0——它们要等下一个 AppendEntries 里的 leaderCommit 才知道。</span>"},
   {t:"N1 在广播 leaderCommit 之前崩溃了",
    nodes:[["N1","D",2,"1,2,3",3,3],["N2","F",2,"1,2,3",0,0],["N3","F",2,"1,2,3",0,0],["N4","F",2,"—",0,0],["N5","F",2,"—",0,0]],
    note:"<strong>「x=3 已提交」这个事实随着 N1 一起消失了。</strong><br>"+
         "日志还在（N2、N3 手里有），但没有任何活着的节点知道它已经提交。<br>"+
         "<em>这正是 commitIndex 不持久化、也不在节点间传递的代价——它是可推导的，但要有人去推。</em>"},
   {t:"N2 当选任期 3 的 Leader",
    nodes:[["N2","L",3,"1,2,3",0,0],["N3","F",3,"1,2,3",0,0],["N4","F",3,"—",0,0],["N5","F",3,"—",0,0],["N1","D",2,"1,2,3",3,3]],
    note:"N2 日志最新（3 条），拿到 {N2,N3,N4} 的票当选。<br>"+
         "但它的 <code>commitIndex</code> 是 <strong style='color:var(--crit)'>0</strong>。<br>"+
         "它想提交 index 1~3 吗？想。能吗？<strong>不能</strong>——那是任期 2 的条目，<u>Figure 8 那条限制不让它直接提交</u>。"}
  ];
  if(noop){
    base.push({t:"N2 立刻 append 一条 no-op（index 4, 任期 3）并复制",
     nodes:[["N2","L",3,"1,2,3,<b style='color:var(--s3)'>ø</b>",4,4],["N3","F",3,"1,2,3,ø",0,0],["N4","F",3,"1,2,3,ø",0,0],["N5","F",3,"—",0,0],["N1","D",2,"1,2,3",3,3]],
     note:"no-op 是<strong>当前任期</strong>的条目，复制到 {N2,N3,N4} 过半后<u>可以直接提交</u>。<br>"+
          "而提交是<strong>前缀性</strong>的——index 4 一提交，1、2、3 <strong style='color:var(--s3)'>被顺带提交了</strong>。<br>"+
          "<code>commitIndex: 0 → 4</code>，然后 apply 追上，<code>lastApplied = 4</code>。"});
    base.push({t:"客户端 ReadIndex 读 x",ok:true,
     nodes:[["N2","L",3,"1,2,3,ø",4,4],["N3","F",3,"1,2,3,ø",4,4],["N4","F",3,"1,2,3,ø",4,4],["N5","F",3,"—",0,0],["N1","D",2,"1,2,3",3,3]],
     note:"① <code>readIndex := commitIndex = 4</code>　② 心跳过半确认 ✓　③ <code>lastApplied=4 &gt;= 4</code> ✓<br>"+
          "返回 <strong style='font-size:16px;color:var(--ok)'>x = 3</strong>　—— 正是客户端上次写成功的那个值。<strong>线性一致 ✓</strong>"});
  }else{
    base.push({t:"N2 不发 no-op，安静地等着",
     nodes:[["N2","L",3,"1,2,3",0,0],["N3","F",3,"1,2,3",0,0],["N4","F",3,"—",0,0],["N5","F",3,"—",0,0],["N1","D",2,"1,2,3",3,3]],
     note:"没有新写入进来，也没有 no-op。<br>"+
          "<strong style='color:var(--crit)'>commitIndex 会一直停在 0</strong>——不是暂时的，是永久的，直到下一次有写入。<br>"+
          "状态机一条都没 apply，<code>lastApplied = 0</code>。"});
    base.push({t:"客户端 ReadIndex 读 x",bad:true,
     nodes:[["N2","L",3,"1,2,3",0,0],["N3","F",3,"1,2,3",0,0],["N4","F",3,"—",0,0],["N5","F",3,"—",0,0],["N1","D",2,"1,2,3",3,3]],
     note:"① <code>readIndex := commitIndex = <b style='color:var(--crit)'>0</b></code>　② 心跳过半确认 <span style='color:var(--ok)'>✓ 通过</span>　③ <code>lastApplied=0 &gt;= 0</code> <span style='color:var(--ok)'>✓ 通过</span><br>"+
          "返回 <strong style='font-size:16px;color:var(--crit)'>（初始值，x 不存在）</strong><br>"+
          "<strong>可客户端明明收到过「x=3 写入成功」。</strong>这是一次货真价实的线性一致性破裂——<br>"+
          "<em>而 ReadIndex 的三步一步没少、全部通过了。</em>问题出在第 1 步拿到的 <code>commitIndex</code> 本身就是错的。"});
  }
  return base;
}
function draw2(){
  const noop=$("#b2noop").checked, st=steps2(noop), i=Math.min(S2.i,st.length-1), s=st[i];
  $("#c2t").innerHTML="步骤 "+(i+1)+" / "+st.length+" · "+s.t;
  let h="";
  for(const [nm,role,term,log,cm,ap] of s.nodes){
    const bc=role==="L"?"L":role==="D"?"D":"F";
    const lbl=role==="L"?"LEADER":role==="D"?"CRASHED":"follower";
    h+='<div class="rnode"'+(role==="D"?' style="opacity:.45"':'')+'>'+
       '<div class="h"><span>'+nm+'</span><span class="badge '+bc+'">'+lbl+'</span></div>'+
       '<div style="font-family:var(--mono);font-size:11.5px;color:var(--ink-2)">term '+term+'<br>log ['+log+']<br>'+
       'commit <b style="color:'+(cm>0?"var(--s3)":"var(--ink-3)")+'">'+cm+'</b>　applied <b style="color:'+(ap>0?"var(--s1)":"var(--ink-3)")+'">'+ap+'</b></div></div>';
  }
  $("#v2").innerHTML=h;
  const cls=s.bad?"crit":s.ok?"ok":"";
  $("#o2").innerHTML='<div class="note '+cls+'" style="margin:0"><div class="note-h">'+
    '<span class="dot" style="background:var(--'+(s.bad?"crit":s.ok?"ok":"s1")+')"></span>'+s.t+'</div>'+
    '<p style="margin-bottom:0">'+s.note+'</p></div>';
  $("#b2step").textContent = i>=st.length-1 ? "已到最后一步" : "下一步 ▸";
  $("#b2step").disabled = i>=st.length-1;
}
$("#b2step").onclick=()=>{S2.i++;draw2();};
$("#b2reset").onclick=()=>{S2.i=0;draw2();};
$("#b2noop").onchange=()=>{S2.i=0;draw2();};
draw2();
