/* ══════════════════════════════════════════════════════════════════
   实验 3 · Quorum vs Raft
   ══════════════════════════════════════════════════════════════════ */
function rng(seed){let s=(seed>>>0)||1;return()=>{s^=s<<13;s>>>=0;s^=s>>>17;s^=s<<5;s>>>=0;return s/4294967296;};}
const VN=["A","B","C","D"], VC=["var(--s1)","var(--s2)","var(--s3)","var(--s4)"];
const LOSS=0.22;
function bind3(){
  const ids=[["i3n","l3n"],["i3w","l3w"],["i3r","l3r"],["i3c","l3c"],["i3s","l3s"]];
  for(const [a,b] of ids){$("#"+a).oninput=()=>{
    if(a==="i3n"){const n=+$("#i3n").value;$("#i3w").max=n;$("#i3r").max=n;
      if(+$("#i3w").value>n)$("#i3w").value=n; if(+$("#i3r").value>n)$("#i3r").value=n;
      $("#l3w").textContent=$("#i3w").value; $("#l3r").textContent=$("#i3r").value;}
    $("#"+b).textContent=$("#"+a).value; run3();};}
}
function chip3(v){
  if(v<0)return '<span class="chip" style="color:var(--ink-3)">∅</span>';
  return '<span class="chip" style="background:'+VC[v]+';border-color:'+VC[v]+';color:#fff">x='+VN[v]+'</span>';
}
function run3(){
  const N=+$("#i3n").value,W=+$("#i3w").value,R=+$("#i3r").value,C=+$("#i3c").value,seed=+$("#i3s").value;
  const rnd=rng(seed*2654435761);
  /* ---------- ① Dynamo 式 quorum ---------- */
  const deliv=[]; // deliv[c][r] = true/false
  for(let c=0;c<C;c++){const row=[];for(let r=0;r<N;r++)row.push(rnd()>LOSS);deliv.push(row);}
  const wok=[]; for(let c=0;c<C;c++)wok.push(deliv[c].filter(Boolean).length>=W);
  const repD=[]; const arrivals=[];
  for(let r=0;r<N;r++){
    const got=[];for(let c=0;c<C;c++)if(deliv[c][r])got.push(c);
    for(let i=got.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[got[i],got[j]]=[got[j],got[i]];}
    arrivals.push(got); repD.push(got.length?got[got.length-1]:-1);
  }
  const distinctAll=new Set(repD.filter(v=>v>=0));
  const readSet=[];{const idx=[];for(let r=0;r<N;r++)idx.push(r);
    for(let i=idx.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[idx[i],idx[j]]=[idx[j],idx[i]];}
    for(let i=0;i<R;i++)readSet.push(idx[i]);}
  const readVers=new Set(readSet.map(r=>repD[r]).filter(v=>v>=0));
  let ha='<div style="font-size:12.5px;color:var(--ink-2);margin-bottom:8px">'+
    C+' 个客户端<strong>同时</strong>向任意副本写同一个 key；每个写各自发往全部 '+N+' 个副本，收到 '+W+' 个 ack 就算成功。<br>'+
    '<span style="color:var(--ink-3)">网络有 '+Math.round(LOSS*100)+'% 丢包，各副本收到的<u>顺序</u>也不同。</span></div>';
  ha+='<table style="margin:0"><thead><tr><th style="width:22%">副本</th><th style="width:34%">收到的到达顺序</th><th>最终保存</th></tr></thead><tbody>';
  for(let r=0;r<N;r++){
    ha+='<tr><td><code>R'+(r+1)+'</code></td><td style="font-family:var(--mono);font-size:11.5px">'+
        (arrivals[r].length?arrivals[r].map(c=>VN[c]).join(" → "):'<span style="color:var(--ink-3)">（都没收到）</span>')+
        '</td><td>'+chip3(repD[r])+'</td></tr>';
  }
  ha+='</tbody></table>';
  ha+='<div style="margin-top:10px;font-size:13px">写入结果：'+
      wok.map((o,c)=>'<span class="chip" style="margin-right:5px;'+(o?'':'opacity:.5')+'">x='+VN[c]+(o?' 成功':' 失败')+'</span>').join("")+'</div>';
  ha+='<div style="margin-top:8px;font-size:13px">读 R='+R+' 个副本 {'+readSet.map(r=>"R"+(r+1)).join(",")+'} → 拿回 <strong style="color:'+
      (readVers.size>1?"var(--crit)":"var(--ink)")+'">'+readVers.size+' 个不同版本</strong>'+
      (readVers.size>1?'　<span style="color:var(--crit)">⇒ 必须由读端裁决（向量时钟 / LWW / CRDT）</span>':'')+'</div>';
  $("#d3a").innerHTML=ha;
  /* ---------- ② Raft ---------- */
  const order=[];for(let c=0;c<C;c++)order.push(c);
  for(let i=order.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[order[i],order[j]]=[order[j],order[i]];}
  const maj=Math.floor(N/2)+1;
  let hb='<div style="font-size:12.5px;color:var(--ink-2);margin-bottom:8px">'+
    '同样 '+C+' 个客户端同时写，但全部请求<strong>先到 Leader</strong>。Leader 按到达先后分配 index，再复制；'+
    '过半（'+maj+'/'+N+'）确认即提交。<br><span style="color:var(--ink-3)">同样的丢包率，靠重试 + nextIndex 回退补齐。</span></div>';
  hb+='<div class="grid-wrap"><div class="tape">';
  order.forEach((c,i)=>{hb+='<div class="cell commit"><div><b>'+(i+1)+'</b><br><span style="font-size:10px">x='+VN[c]+'</span></div></div>';});
  hb+='</div></div><div style="font-size:12px;color:var(--ink-3);margin-top:4px">Leader 的日志（所有副本最终一模一样）</div>';
  hb+='<table style="margin:12px 0 0"><thead><tr><th style="width:22%">副本</th><th style="width:34%">日志</th><th>最终保存</th></tr></thead><tbody>';
  const winner=order[order.length-1];
  for(let r=0;r<N;r++){
    hb+='<tr><td><code>R'+(r+1)+'</code>'+(r===0?' <span class="badge L">LEADER</span>':'')+'</td>'+
        '<td style="font-family:var(--mono);font-size:11.5px">'+order.map(c=>VN[c]).join(" → ")+'</td>'+
        '<td>'+chip3(winner)+'</td></tr>';
  }
  hb+='</tbody></table>';
  hb+='<div style="margin-top:10px;font-size:13px">写入结果：'+
      order.map(c=>'<span class="chip" style="margin-right:5px">x='+VN[c]+' 成功</span>').join("")+
      '<span style="color:var(--ink-3)">（全部成功，且有明确先后）</span></div>';
  hb+='<div style="margin-top:8px;font-size:13px">读 Leader 一个 → 拿回 <strong style="color:var(--ok)">1 个版本</strong>　'+
      '<span style="color:var(--ink-3)">⇒ 无需任何冲突解决</span></div>';
  $("#d3b").innerHTML=hb;
  /* ---------- 结论 ---------- */
  const div=distinctAll.size;
  let ho='<div class="note '+(div>1?"crit":"")+'" style="margin:0"><div class="note-h">'+
    '<span class="dot" style="background:var(--'+(div>1?"crit":"s1")+')"></span>对照</div>'+
    '<table style="margin:8px 0 0"><thead><tr><th style="width:34%"></th><th style="width:33%">Dynamo 式 Quorum</th><th>Raft</th></tr></thead><tbody>'+
