// Lab 3-C · 持久化、快照、成员变更与线性一致读
//
// 运行：  cd go/lab03c && go run .
// 调参：  go run . -lose votedfor     ← 只看丢掉 votedFor 的后果
//
//	go run . -lose term | log
//
// 配套课件：courseware/ch03c-production-raft.html
package main

import (
	"flag"
	"fmt"
	"strings"

	"dsc/internal/tui"
)

var (
	nF      = flag.Int("n", 5, "节点数")
	delayF  = flag.Int64("delay", 20, "单向网络延迟（毫秒）")
	jitterF = flag.Int64("jitter", 10, "延迟抖动")
	seedF   = flag.Int64("seed", 42, "随机种子")
	loseF   = flag.String("lose", "", "只跑某一种失去持久化的场景：term | votedfor | log")
	trialsF = flag.Int("trials", 60, "每组实验的种子数")
)

const tick = 5

func mk(seed int64, cfg func(*Cluster)) *Cluster {
	return mkw(seed, 300, 0, cfg)
}

// mkw 允许指定选举超时窗口与丢包率。
// 窗口设成 0（固定超时）会让多个节点【同时】发起选举 ——
// 这正是暴露「votedFor 没落盘」的必要条件：得先有两个 candidate 在抢同一个任期。
func mkw(seed int64, window int64, loss float64, cfg func(*Cluster)) *Cluster {
	net := NewNetwork(*nF, *delayF, *jitterF, loss, seed)
	c := New(*nF, net, 400, window, seed)
	c.LeaseMs = 250
	if cfg != nil {
		cfg(c)
	}
	return c
}
func run(c *Cluster, ms int64) {
	for t := int64(0); t < ms; t += tick {
		c.Step(tick)
	}
}

func main() {
	flag.Parse()
	fmt.Printf("\n配置：%d 节点 ｜ 延迟 %d±%dms ｜ 每组 %d 个种子 ｜ 种子基准 %d\n",
		*nF, *delayF, *jitterF, *trialsF, *seedF)
	lab3c1()
	lab3c2()
	lab3c3()
	lab3c4()
	epilogue()
}

// ═══════════════════════════════════════════════════════════════════════
// Lab 3C-1：持久化 —— 丢掉哪一样，哪条安全性倒下
// ═══════════════════════════════════════════════════════════════════════
func lab3c1() {
	tui.HeadN("3C-1", "持久化与崩溃重启", "分别丢掉三样状态中的一样，看哪条安全性倒下")

	w := []int{28, 14, 14, 14, 18}
	al := "LRRRR"
	tui.TableHeadA([]string{"磁盘上丢了什么", "违规的种子", "选举安全性", "状态机安全性", "结论"}, w, al)

	try := func(label string, lt, lv, ll bool) {
		bad, elec, sm := 0, 0, 0
		for seed := int64(1); seed <= int64(*trialsF); seed++ {
			// 固定超时 + 丢包 ⇒ 经常出现两个 candidate 抢同一个任期，
			// 这是让「忘记投过票」真正造成脑裂的必要土壤。
			c := mkw(*seedF+seed, 0, 0.12, func(c *Cluster) {
				c.LoseTerm, c.LoseVote, c.LoseLog = lt, lv, ll
			})
....
	return s
}

// Head 打印一个实验的标题块。
func Head(part, n int, title, subtitle string) {
	fmt.Printf("\n%s\n", strings.Repeat("═", 78))
	fmt.Printf("  Lab %d-%d · %s\n  %s\n", part, n, title, subtitle)
	fmt.Printf("%s\n", strings.Repeat("═", 78))
}

// Row 打印一行「键 + 值」。
func Row(k string, v ...any) {
	fmt.Printf("    %s %s\n", PadR(k, 30), fmt.Sprint(v...))
}

// TableHead / TableRow 按显示宽度对齐：第一列左对齐，其余右对齐。
func TableHead(cols []string, w []int) { TableHeadA(cols, w, defaultAlign(len(cols))) }
func TableRow(cells []string, w []int) { TableRowA(cells, w, defaultAlign(len(cells))) }

func defaultAlign(n int) string {
	if n == 0 {
		return ""
	}
	return "L" + strings.Repeat("R", n-1)
}

// TableHeadA / TableRowA 支持逐列指定对齐，align 形如 "LRRL"（L 左对齐，R 右对齐）。
func TableHeadA(cols []string, w []int, align string) {
	fmt.Println(layout(cols, w, align))
	t := 0
	for _, x := range w {
		t += x
	}
	fmt.Printf("    %s\n", strings.Repeat("─", t))
}

func TableRowA(cells []string, w []int, align string) { fmt.Println(layout(cells, w, align)) }

func layout(cells []string, w []int, align string) string {
	line := "    "
	for i, c := range cells {
		a := byte('R')
		if i < len(align) {
			a = align[i]
		}
		if a == 'L' {
			line += PadR(c, w[i])
		} else {
			line += PadL(c, w[i])
		}
	}
	return strings.TrimRight(line, " ")
}

func Bar(n int) string { return strings.Repeat("═", n) }

// HeadN 与 Head 相同，但实验编号由调用方自己给（比如 "3A-1"）。
func HeadN(label, title, subtitle string) {
	fmt.Printf("\n%s\n", strings.Repeat("═", 78))
	fmt.Printf("  Lab %s · %s\n  %s\n", label, title, subtitle)
	fmt.Printf("%s\n", strings.Repeat("═", 78))
}

