// Lab 3D-2：no-op —— 新 Leader 的 commitIndex 从哪来
// ═══════════════════════════════════════════════════════════════════════
func lab3d2() {
	tui.HeadN("3D-2", "no-op 条目的必要性", "新 Leader 不发空日志，ReadIndex 三步走完照样读到旧值")

	fmt.Printf(`
