      任期 2：Leader 把 %d 条写复制到了过半节点，然后崩溃。
              分支 ①（约一半概率）它崩之前【已经推进 commitIndex 并回复客户端成功】；
              分支 ②                它还没来得及推进 commitIndex。
              两种情况下它都没来得及广播 leaderCommit ——
              「已提交」这个事实随它一起消失了。
      任期 3：某个持有这些日志的节点当选，它的 commitIndex = 0。
              受 Figure 8 限制，它【不能】直接提交任期 2 的条目。
      然后客户端用完整的 ReadIndex（三步一步不少）来读。
`, *entriesF)

	w := []int{22, 20, 18, 18, 16}
	al := "LRRRR"
	tui.TableHeadA([]string{"新 Leader 上任后", "读到旧值(违规)", "读到正确值", "正确拒绝", "本就无 ack"}, w, al)

	type res struct{ stale, correct, rejected, noack int }
	run := func(noop bool) res {
		var r res
		rnd := NewRand(*seedF * 31)
		for s := 0; s < *seedsF; s++ {
			acked := rnd.Float() < 0.5   // 分支 ① / ②
			early := rnd.Float() < 0.35  // 读请求到得早不早
			switch RunNoop(*entriesF, acked, noop, early) {
			case OutcomeStale:
				r.stale++
			case OutcomeCorrect:
				r.correct++
			case OutcomeRejected:
				r.rejected++
			case OutcomeNoAck:
				r.noack++
			}
		}
		return r
	}
	a := run(false)
	b := run(true)
	tui.TableRowA([]string{"不发 no-op", fmt.Sprintf("%d", a.stale), fmt.Sprintf("%d", a.correct),
		fmt.Sprintf("%d", a.rejected), fmt.Sprintf("%d", a.noack)}, w, al)
	tui.TableRowA([]string{"发 no-op（正确）", fmt.Sprintf("%d", b.stale), fmt.Sprintf("%d", b.correct),
		fmt.Sprintf("%d", b.rejected), fmt.Sprintf("%d", b.noack)}, w, al)

	fmt.Printf(`
    结论
      · 不发 no-op：%d/%d 个种子读到了旧值，而客户端【收到过写入成功】——
        这是货真价实的线性一致性破裂，且 ReadIndex 三步一步没少、全部通过。
        问题出在第 1 步拿到的 commitIndex 本身就是错的。
      · 发 no-op：违规 0 次。no-op 是【当前任期】的条目，可以直接提交；
        提交是前缀性的 ⇒ 任期 2 那几条被顺带提交 ⇒ commitIndex 到位。
      · 那 %d 次「正确拒绝」也很重要：no-op 还没提交完时，
        真实系统（etcd / TiKV）会拒绝服务读，而不是拿一个没到位的 commitIndex 去凑合。
        【给你错误，而不是给你错的数据。】
      · 「本就无 ack」的那些不算违规：那次写的结果本来就是 Part 0 说的「第三态」。
`, a.stale, *seedsF, b.rejected)
}

