    // ══════════════════════════════════════════════════════════════════════
    // Lab 3D-4：冷启动 —— 配置从哪来
    // ══════════════════════════════════════════════════════════════════════
    record NodeCfg(String id, List<String> cluster, String state, String token, int gen, String dataDir) {}
    static final class Group {
        int believes, need; List<String> present = new ArrayList<>(); boolean leader;
    }

    /**
     * 把一组启动参数变成实际形成的集群。
     * 分组规则（简化，但抓住了本质）：两个节点能进同一个 Raft 组，
     * 必须 token 相同、成员列表相同、且属于同一个集群实例（gen 建模 cluster ID）。
     * 任何一项对不上，它们就是两个互不相干的集群 —— 而且【谁都不会报错】。
     */
    static List<Group> bootstrap(List<NodeCfg> nodes) {
        Map<String, Group> m = new LinkedHashMap<>();
        for (NodeCfg nd : nodes) {
            List<String> cl = new ArrayList<>(nd.cluster()); Collections.sort(cl);
            String sig = nd.token() + "/" + String.join(",", cl) + "/gen" + nd.gen();
            Group g = m.computeIfAbsent(sig, k -> {
                Group x = new Group();
                x.believes = nd.cluster().size();
                x.need = nd.cluster().size() / 2 + 1;
                return x;
            });
            g.present.add(nd.id());
        }
        List<Group> out = new ArrayList<>(m.values());
        for (Group g : out) g.leader = g.present.size() >= g.need;
        return out;
    }

