/* ══════════════════════════════════════════════════════════════════
   迷你事务引擎
   —— MVCC 版本链 + ReadView + 行锁 + 范围锁 + 串行执行
   下面那张矩阵的每一格都是这个引擎真的跑出来的，不是抄的表。
   ══════════════════════════════════════════════════════════════════ */
const LEVELS=["RU","RC","RR","RRLOCK","SER"];
const LVNAME={RU:"READ<br>UNCOMMITTED",RC:"READ<br>COMMITTED",RR:"REPEATABLE<br>READ",
  RRLOCK:"RR +<br>FOR UPDATE",SER:"SERIA-<br>LIZABLE"};

class Engine{
  constructor(level,init){
    this.level=level;
    this.rows={};                 // key -> [{trx,val}] 新 → 旧
    for(const k in init) this.rows[k]=[{trx:0,val:init[k]}];
    this.committed=new Set([0]);  // 已提交的事务 id
    this.active=new Set();        // 仍活跃的事务 id
    this.xlock={};                // key -> 持锁的事务 id（持有到提交）
    this.rlock=[];                // {trx, tag} 范围锁（共享）
    this.tx={};                   // 逻辑编号 t -> 事务对象
    this.nextId=101;
    this.trace=[];                // 给可视化用的时序记录
    this.deadlock=false;
  }
  // ── ReadView：四个字段 ──────────────────────────────────────────
  mkRV(x){
    const mids=[...this.active].filter(i=>i!==x.id).sort((a,b)=>a-b);
    return {mids, min: mids.length?mids[0]:this.nextId, max:this.nextId, creator:x.id};
  }
  // 四步可见性判定 —— 和 InnoDB 一模一样
  visible(trx,rv){
    if(trx===rv.creator) return true;
    if(trx<rv.min) return true;
    if(trx>=rv.max) return false;
    if(rv.mids.includes(trx)) return false;
    return true;
  }
  // 快照读：沿版本链从新到旧，第一个可见的就是答案
  snapRead(key,rv){
    const ch=this.rows[key]||[];
    for(const v of ch) if(this.visible(v.trx,rv)) return v.val;
    return undefined;
  }
  // 当前读：最新的【已提交】版本
  curRead(key){
    const ch=this.rows[key]||[];
    for(const v of ch) if(this.committed.has(v.trx)) return v.val;
    return undefined;
  }
  // 脏读：最新版本，不管提交没提交
  dirtyRead(key){
    const ch=this.rows[key]||[];
    return ch.length?ch[0].val:undefined;
  }
  readFor(x,key,lockable){
    if(this.level==="RU") return this.dirtyRead(key);
    if(lockable&&(this.level==="RRLOCK"||this.level==="SER")) return this.curRead(key);
    if(this.level==="RC") return this.snapRead(key,this.mkRV(x));   // 每条语句新建 ReadView
    if(!x.rv) x.rv=this.mkRV(x);                                     // RR：只建一次，之后复用
    return this.snapRead(key,x.rv);
  }
  matching(x,pred,lockable){
    const out=[];
    for(const k in this.rows){
      const v=this.readFor(x,k,lockable);
      if(v!==undefined&&pred.test(k,v)) out.push(k);
    }
    return out;
  }
  // ── 锁 ─────────────────────────────────────────────────────────
  lockBusy(key,id){ const o=this.xlock[key]; return o!==undefined&&o!==id&&this.active.has(o); }
  rangeBusy(tag,id){ return this.rlock.some(r=>r.tag===tag&&r.trx!==id&&this.active.has(r.trx)); }
  // ── 执行一步；返回 "ok" | "blocked" ────────────────────────────
  step(s){
    let x=this.tx[s.t];
    if(s.op==="begin"){
      x={t:s.t,id:this.nextId++,rv:null,last:undefined,done:false};
      this.tx[s.t]=x; this.active.add(x.id);
      this.trace.push({t:s.t,txt:"BEGIN",kind:"c"}); return "ok";
    }
    if(!x) return "ok";
    switch(s.op){
      case "read":{
        if(s.lockable&&(this.level==="RRLOCK"||this.level==="SER")){
          if(this.lockBusy(s.key,x.id)) return "blocked";
          this.xlock[s.key]=x.id;
        }
        const v=this.readFor(x,s.key,s.lockable); x.last=v;
        this.trace.push({t:s.t,kind:"r",
          txt:(s.lockable&&(this.level==="RRLOCK"||this.level==="SER")?"SELECT "+s.key+" FOR UPDATE":"SELECT "+s.key)+" → "+v});
        return "ok";
      }
      case "scan":{
        const keys=this.matching(x,s.pred,s.lockable);
        if(s.lockable&&(this.level==="RRLOCK"||this.level==="SER")){
          for(const k of keys) if(this.lockBusy(k,x.id)) return "blocked";
          if(this.rangeBusy(s.pred.tag,x.id)&&s.exclusiveRange) return "blocked";
          for(const k of keys) this.xlock[k]=x.id;
          this.rlock.push({trx:x.id,tag:s.pred.tag});
        }
        x.last=keys.length;
        this.trace.push({t:s.t,kind:"r",
          txt:"SELECT count(*) WHERE "+s.pred.label+(s.lockable&&(this.level==="RRLOCK"||this.level==="SER")?" FOR UPDATE":"")+" → "+keys.length});
        return "ok";
      }
      case "write":{
        if(s.guardMin!==undefined&&!(x.last>=s.guardMin)){
          this.trace.push({t:s.t,kind:"c",txt:"if (上次读到 "+x.last+" >= "+s.guardMin+") 不成立 → 放弃写入"});
          return "ok";
        }
        if(this.level!=="RU"&&this.lockBusy(s.key,x.id)) return "blocked";
        this.xlock[s.key]=x.id;
        const val=s.delta!==undefined?(x.last+s.delta):s.val;
        (this.rows[s.key]=this.rows[s.key]||[]).unshift({trx:x.id,val});
        this.trace.push({t:s.t,kind:"w",txt:"UPDATE "+s.key+" = "+val});
        return "ok";
      }
      case "insert":{
        if(s.guardMax!==undefined&&!(x.last<=s.guardMax)){
          this.trace.push({t:s.t,kind:"c",txt:"if (上次读到 "+x.last+" <= "+s.guardMax+") 不成立 → 放弃插入"});
          return "ok";
        }
        if((this.level==="RRLOCK"||this.level==="SER")&&s.tag&&this.rangeBusy(s.tag,x.id)) return "blocked";
        this.xlock[s.key]=x.id;
        (this.rows[s.key]=this.rows[s.key]||[]).unshift({trx:x.id,val:s.val});
        this.trace.push({t:s.t,kind:"w",txt:"INSERT "+s.key+" = "+s.val});
        return "ok";
      }
      case "commit":
        this.committed.add(x.id); this.active.delete(x.id); x.done=true;
        this.trace.push({t:s.t,kind:"c",txt:"COMMIT"}); return "ok";
      case "abort":
        this.active.delete(x.id); x.done=true;
        for(const k in this.rows) this.rows[k]=this.rows[k].filter(v=>v.trx!==x.id);
        this.trace.push({t:s.t,kind:"c",txt:"ROLLBACK"}); return "ok";
    }
    return "ok";
  }
  // 按给定时序执行；某一步被锁挡住就让它排队，等持锁方提交后再放行。
  // 所有事务都卡住 = 死锁 ⇒ 中止最后一个（真实引擎也是这么干的）
  run(steps){
    const q=[...steps]; const waiting={}; let guard=0;
    while(q.length&&guard++<4000){
      let moved=false;
      for(let i=0;i<q.length;i++){
        const s=q[i];
        if(waiting[s.t]) continue;
        const r=this.step(s);
        if(r==="ok"){ q.splice(i,1); moved=true; break; }
        waiting[s.t]=true;
        this.trace.push({t:s.t,kind:"blk",txt:"（被锁阻塞，等待）"});
      }
      if(!moved){
        const stuck=Object.keys(waiting).filter(t=>waiting[t]);
        if(stuck.length===0) break;
        // 有人在等，但没人能推进 ⇒ 死锁。中止其中一个，放掉它的锁。
        this.deadlock=true;
        const victim=stuck[stuck.length-1];
        const x=this.tx[victim];
        if(x){ this.active.delete(x.id);
          for(const k in this.rows) this.rows[k]=this.rows[k].filter(v=>v.trx!==x.id);
          this.rlock=this.rlock.filter(r=>r.trx!==x.id);
          this.trace.push({t:+victim,kind:"blk",txt:"⚡ 死锁，本事务被选为牺牲者并回滚"});
        }
        for(let i=q.length-1;i>=0;i--) if(q[i].t==+victim) q.splice(i,1);
        for(const t in waiting) waiting[t]=false;
        continue;
      }
      for(const t in waiting) waiting[t]=false;   // 有人推进了，重新唤醒所有等待者
    }
    return this.trace;
  }
  finalVal(key){ return this.curRead(key); }
  countWhere(pred){ let n=0; for(const k in this.rows){const v=this.curRead(k); if(v!==undefined&&pred.test(k,v))n++;} return n; }
}
// 串行化：把同一个事务的步骤聚到一起，一个跑完再跑下一个
function serialize(steps){
  const order=[],buckets={};
  for(const s of steps){ if(!buckets[s.t]){buckets[s.t]=[];order.push(s.t);} buckets[s.t].push(s); }
  return order.flatMap(t=>buckets[t]);
}
