 steps:[{t:1,op:"begin"},{t:2,op:"begin"},
  {t:1,op:"read",key:"x",lockable:true},{t:2,op:"read",key:"x",lockable:true},
  {t:1,op:"write",key:"x",delta:10},{t:2,op:"write",key:"x",delta:10},
  {t:1,op:"commit"},{t:2,op:"commit"}],
 check:e=>({bad:e.finalVal("x")!==120,
   detail:"两次各加 10，期望 120，实际 "+e.finalVal("x")}),
 why:"标准的<strong>读-改-写</strong>循环：两个事务都读到 100，在应用里各自算出 110，都写回去 ⇒ <u>只加了一次</u>。<br>"+
   "<strong>RR 这一格是红的</strong>——这就是为什么「我们用 RR 所以并发安全」是错的。RR 保证的是「我读到的不变」，"+
   "而这里的问题恰恰是<em>你读到的确实没变，但它已经过时了</em>。<br>"+
   "两种修法：① <code>SELECT ... FOR UPDATE</code>（这一列）；"+
   "② 把整个读-改-写写成一条原子 SQL <code>UPDATE x = x + 10</code>——那是当前读，天然带锁。<br>"+
   "<em>也就是说：能不能防住，取决于你怎么写 SQL，而不取决于隔离级别。</em>"},

{id:"ws",name:"写偏斜",en:"write skew",ansi:false,
 init:{"doc:alice":1,"doc:bob":1},
 steps:[{t:1,op:"begin"},{t:2,op:"begin"},
  {t:1,op:"scan",pred:P_ONCALL,lockable:true},{t:2,op:"scan",pred:P_ONCALL,lockable:true},
  {t:1,op:"write",key:"doc:alice",val:0,guardMin:2},
  {t:2,op:"write",key:"doc:bob",val:0,guardMin:2},
  {t:1,op:"commit"},{t:2,op:"commit"}],
 check:e=>({bad:e.countWhere(P_ONCALL)<1,
   detail:"最终在岗医生数 "+e.countWhere(P_ONCALL)+"（不变量要求 >= 1）"}),
 why:"<strong>这一章的主角。</strong>两个医生同时检查「在岗 &gt;= 2，我可以走」，都通过，然后各自把<u>自己那一行</u>改成不在岗。<br>"+
   "所有防线都失效，原因是同一个：<strong>它们写的不是同一行。</strong><br>"+
   "· 行锁不冲突 · 那两个 <code>SELECT</code> 是快照读、压根没加锁 · 快照隔离的 first-committer-wins 只检测<em>写-写</em>冲突<br>"+
   "<strong style='color:var(--crit)'>Oracle 的 SERIALIZABLE 也挡不住</strong>（它实际是快照隔离）。<br>"+
   "根因：<em>读到的结果是你决策的前提，而数据库看不见你代码里那个 <code>if</code></em>。<br>"+
   "看 RR+FOR UPDATE 那一格：T2 的 SELECT 被阻塞，等 T1 提交后重新读到 1，它自己的检查就不通过了——<strong>把读物化成锁</strong>。"},

{id:"pws",name:"写偏斜（插入型）",en:"phantom write skew",ansi:false,
 init:{"bk:0":0},
 steps:[{t:1,op:"begin"},{t:2,op:"begin"},
  {t:1,op:"scan",pred:P_ROOM,lockable:true,exclusiveRange:true},
  {t:2,op:"scan",pred:P_ROOM,lockable:true,exclusiveRange:true},
  {t:1,op:"insert",key:"bk:1",val:1,guardMax:0,tag:"roomA"},
  {t:2,op:"insert",key:"bk:2",val:1,guardMax:0,tag:"roomA"},
  {t:1,op:"commit"},{t:2,op:"commit"}],
 check:e=>({bad:e.countWhere(P_ROOM)>1,
   detail:"最终这个时段的预订数 "+e.countWhere(P_ROOM)+"（不变量要求 <= 1）"}),
 why:"两个人同时查「A 会议室 10 点有人订吗」，都查到没有，都插入了预订。<br>"+
   "<strong>比普通写偏斜更难防：连要加锁的那一行都还不存在。</strong>行锁锁不住不存在的行。<br>"+
   "RR+FOR UPDATE 这一格能挡住，靠的是 <strong>Next-Key Lock 里的间隙锁部分</strong>——它锁的正是「空隙」。<br>"+
   "工程上还有两个更稳的办法：<br>"+
   "· <strong>唯一索引</strong>（把「同一时段只能有一条预订」告诉数据库，它就能可靠保护）<br>"+
   "· <strong>物化冲突</strong>：预先建好「会议室 × 时间段」的占位行，把不存在的冲突变成一行真实的行，然后锁它。"}
];

