  const e=new Engine(level,JSON.parse(JSON.stringify(sc.init)));
  e.run(level==="SER"?serialize(sc.steps):sc.steps);
  const v=sc.check(e);
  return {bad:v.bad,detail:v.detail,trace:e.trace,deadlock:e.deadlock};
}
