/* ══════════════════════════════════════════════════════════════════
   实验 3 · 医院值班表：谁能挡住写偏斜
   ══════════════════════════════════════════════════════════════════ */
function skewSteps(D,C,rnd){
  // C 个医生同时发起请假：读一遍在岗人数 → 如果 >= 2 就把自己设成不在岗
  const per=[];
  for(let t=1;t<=C;t++) per.push([
    {t,op:"begin"},
    {t,op:"scan",pred:P_ONCALL,lockable:true},
    {t,op:"write",key:"doc:"+t,val:0,guardMin:2},
    {t,op:"commit"}]);
  // 保持每个事务内部顺序不变，随机交错
  const idx=per.map(()=>0), out=[];
  let left=per.reduce((a,p)=>a+p.length,0);
  while(left>0){
    const avail=[];
    for(let i=0;i<C;i++) if(idx[i]<per[i].length) avail.push(i);
    const pick=avail[Math.floor(rnd()*avail.length)];
    out.push(per[pick][idx[pick]++]); left--;
  }
  return out;
}
function run3(){
  const D=+$("#i3d").value,C=Math.min(+$("#i3c").value,D),N=+$("#i3n").value;
  $("#l3d").textContent=D; $("#l3c").textContent=$("#i3c").value; $("#l3n").textContent=N;
  const cfgs=[["RC","READ COMMITTED"],["RR","REPEATABLE READ"],
              ["RRLOCK","RR + SELECT … FOR UPDATE"],["SER","SERIALIZABLE"]];
  const res=[];
  for(const [lv,nm] of cfgs){
    let bad=0,sumOn=0,blocked=0,gaveUp=0;
    for(let s=1;s<=N;s++){
      const rnd=rng(s*2654435761);
      const init={}; for(let i=1;i<=D;i++) init["doc:"+i]=1;
      const e=new Engine(lv,init);
      const st=skewSteps(D,C,rnd);
      e.run(lv==="SER"?serialize(st):st);
      const on=e.countWhere(P_ONCALL);
      sumOn+=on; if(on<1) bad++;
      if(e.trace.some(x=>x.kind==="blk")) blocked++;
      gaveUp+=e.trace.filter(x=>x.txt&&x.txt.indexOf("放弃写入")>=0).length;
    }
    res.push({lv,nm,bad,avgOn:sumOn/N,blocked,gaveUp});
  }
  let h='<div class="grid-wrap"><table style="margin:0"><thead><tr>'+
    '<th style="width:28%">隔离配置</th><th style="width:18%">不变量被破坏</th>'+
    '<th style="width:16%">平均最终在岗</th><th style="width:18%">出现过锁等待</th><th>主动放弃请假</th>'+
    '</tr></thead><tbody>';
  for(const r of res){
    h+='<tr><td><code>'+r.nm+'</code></td>'+
      '<td><strong style="color:'+(r.bad?"var(--crit)":"var(--ok)")+'">'+r.bad+' / '+N+'</strong></td>'+
      '<td>'+r.avgOn.toFixed(2)+' 人</td>'+
      '<td>'+r.blocked+' / '+N+'</td><td>'+r.gaveUp+' 次</td></tr>';
  }
  h+='</tbody></table></div>';
  const rc=res[0],rr=res[1],lk=res[2],sr=res[3];
  h+='<div class="note '+(rr.bad?"crit":"")+'" style="margin:14px 0 0"><div class="note-h">'+
    '<span class="dot" style="background:var(--'+(rr.bad?"crit":"s1")+')"></span>读这张表</div><p style="margin-bottom:0">';
  if(rr.bad){
    h+='<strong>RC 和 RR 的违规次数几乎一样（'+rc.bad+' vs '+rr.bad+'）。</strong>'+
       '把隔离级别从 RC 调到 RR，对写偏斜<u>没有任何帮助</u>——因为 RR 加强的是「我读到的不变」，'+
       '而这里的问题是<em>你读到的确实没变，只是它已经过时了</em>。<br>';
  }else{
    h+='<span style="color:var(--s4)">这组参数下 RR 恰好没撞出违规</span>——把「同时请假的人数」调大，或者增加试验次数再看。<br>';
  }
  h+='加上 <code>FOR UPDATE</code> 后违规降到 <strong style="color:var(--ok)">'+lk.bad+'</strong>，'+
     '代价是 '+lk.blocked+'/'+N+' 次出现锁等待，以及 '+lk.gaveUp+' 次「有人查到人不够，主动放弃请假」——'+
     '<strong>后者正是我们想要的行为</strong>：不是数据库报错，而是应用自己发现前提不成立。<br>'+
     '<em>加锁把「读」这个动作物化成了一件别人看得见的事，于是数据库终于知道你的读和写之间有因果关系。</em>';
  h+='</p></div>';
  $("#o3").innerHTML=h;
}
