/* ══════════════════════════════════════════════════════════════════
   实验 4 · 2PL vs SSI
   ══════════════════════════════════════════════════════════════════ */
const NKEY=20, HOT=3;
function mkTxns(C,O,hot,rnd){
  const ts=[];
  for(let i=0;i<C;i++){
    const ops=[];
    for(let j=0;j<O;j++){
      const k=(rnd()<hot)?Math.floor(rnd()*HOT):Math.floor(rnd()*NKEY);
      ops.push({key:k,write:rnd()<0.5});
    }
    ts.push({id:i,ops});
  }
  return ts;
}
// 2PL：悲观。拿不到锁就等；所有人都等 = 死锁，中止一个重来。
function sim2PL(txns){
  const st=txns.map(t=>({id:t.id,ops:t.ops,p:0,locks:[],done:false}));
  const owner={};            // key -> {trx, x}
  let tick=0,aborts=0;
  while(st.some(s=>!s.done)&&tick<20000){
    tick++; let moved=false;
    for(const s of st){
      if(s.done) continue;
      const op=s.ops[s.p];
      const o=owner[op.key];
      if(o&&o.trx!==s.id&&(o.x||op.write)){ continue; }   // 锁冲突 ⇒ 等
      if(!o||o.trx!==s.id) { owner[op.key]={trx:s.id,x:op.write}; s.locks.push(op.key); }
      else if(op.write) owner[op.key].x=true;
      s.p++; moved=true;
      if(s.p>=s.ops.length){ s.done=true; for(const k of s.locks) if(owner[k]&&owner[k].trx===s.id) delete owner[k]; s.locks=[]; }
    }
    if(!moved){
      // 死锁：选一个牺牲者中止，释放它的锁，从头重做
      const v=st.filter(s=>!s.done).pop();
      if(!v) break;
      aborts++;
      for(const k of v.locks) if(owner[k]&&owner[k].trx===v.id) delete owner[k];
      v.locks=[]; v.p=0;
    }
  }
  return {tick,aborts,tput:txns.length/tick*100};
}
// SSI：乐观。全速跑完，提交时才检查「我读到的前提有没有被推翻」，被推翻就中止重来。
function simSSI(txns){
  let pending=txns.map(t=>({id:t.id,ops:t.ops})), tick=0, aborts=0;
  const history=[];          // 已提交事务的写集
  let round=0;
  while(pending.length&&round++<200){
    const start=history.length;
    tick+=pending[0].ops.length;              // 本轮所有事务并行跑完各自的 O 步
    const next=[];
    for(const t of pending){
      const rs=new Set(t.ops.filter(o=>!o.write).map(o=>o.key));
      const ws=new Set(t.ops.filter(o=>o.write).map(o=>o.key));
      // 我开始之后提交的事务里，有没有人写了我读过的东西 / 或写了我要写的东西
      let conflict=false;
      for(let i=start;i<history.length;i++){
        for(const k of history[i]) if(rs.has(k)||ws.has(k)){conflict=true;break;}
        if(conflict)break;
      }
      if(conflict){ aborts++; next.push(t); }
      else history.push(ws);
    }
    pending=next;
  }
  return {tick,aborts,tput:txns.length/Math.max(tick,1)*100};
}
function bar(v,max,color){
  const w=Math.max(2,Math.round(v/Math.max(max,1)*100));
  return '<div style="height:8px;background:var(--surface-2);border-radius:4px;overflow:hidden;margin-top:5px">'+
    '<div style="height:100%;width:'+w+'%;background:'+color+'"></div></div>';
}
function run4(){
  const hot=+$("#i4h").value/100,C=+$("#i4c").value,O=+$("#i4o").value,seed=+$("#i4s").value;
  $("#l4h").textContent=+$("#i4h").value; $("#l4c").textContent=C; $("#l4o").textContent=O; $("#l4s").textContent=seed;
  const txns=mkTxns(C,O,hot,rng(seed*2654435761));
  const a=sim2PL(txns.map(t=>({id:t.id,ops:t.ops.slice()})));
  const b=simSSI(txns.map(t=>({id:t.id,ops:t.ops.slice()})));
  const mx=Math.max(a.tick,b.tick), mt=Math.max(a.tput,b.tput);
  const card=(r,c)=>'<div class="stats" style="margin-top:0">'+
    '<div class="stat"><div class="k">总耗时</div><div class="v">'+r.tick+' <span class="u">ticks</span></div>'+bar(r.tick,mx,c)+'</div>'+
    '<div class="stat"><div class="k">中止次数</div><div class="v">'+r.aborts+'</div>'+bar(r.aborts,Math.max(a.aborts,b.aborts),c)+'</div>'+
    '<div class="stat"><div class="k">吞吐</div><div class="v">'+r.tput.toFixed(1)+' <span class="u">/100t</span></div>'+bar(r.tput,mt,c)+'</div>'+
