// 进度保证：编号最小的活跃事务永远不会被选为牺牲者 ⇒ 它一定能跑完，然后轮到下一个。
function sim2PL(txns){
  const st=txns.map(t=>({id:t.id,ops:t.ops,p:0,locks:[],done:false,cool:0}));
  const owner={};
  let tick=0,aborts=0,wasted=0,work=0;
  while(st.some(s=>!s.done)&&tick<8000){
    tick++;
    let budget=PAR, moved=false; const waitFor={};
    for(const s of st){
      if(s.done||budget<=0) continue;
      if(s.cool>0){ s.cool--; moved=true; continue; }
      const op=s.ops[s.p], o=owner[op.key];
      if(o&&o.trx!==s.id&&(o.x||op.write)){ waitFor[s.id]=o.trx; continue; }
      if(!o||o.trx!==s.id){ owner[op.key]={trx:s.id,x:op.write}; s.locks.push(op.key); }
      else if(op.write) owner[op.key].x=true;
      s.p++; work++; budget--; moved=true;
      if(s.p>=s.ops.length){ s.done=true;
        for(const k of s.locks) if(owner[k]&&owner[k].trx===s.id) delete owner[k]; s.locks=[]; }
    }
    if(moved) continue;
    const alive=st.filter(s=>!s.done); if(!alive.length) break;
    const protectedId=alive[0].id;                 // 编号最小的：豁免，保证一定有进展
    const cand=alive.filter(s=>s.id!==protectedId&&waitFor[s.id]!==undefined);
    const pool=(cand.length?cand:alive.filter(s=>s.id!==protectedId));
    if(!pool.length) break;
    pool.sort((x,y)=>x.p-y.p);                     // 挑已做的功最少的，浪费最小
    const v=pool[0];
    aborts++; wasted+=v.p;
    for(const k of v.locks) if(owner[k]&&owner[k].trx===v.id) delete owner[k];
    v.locks=[]; v.p=0; v.cool=2;
  }
  return {tick,aborts,wasted,work,tput:txns.length/Math.max(tick,1)*100};
}

// SSI：乐观。谁也不等，全速往前跑；跑完一整个事务才验证
//   「我读到的前提有没有被别人推翻」——被推翻就整个重做。
// 验证条件用的是 SSI 的危险结构近似：
//   ① 写-写冲突（快照隔离本来就要求的 first-committer-wins），或
//   ② 双向的读-写反依赖（我读了它写的，同时它读了我写的）—— 这才是真正会成环的那种。
// 关键性质：中止 = 这一轮做的功【全部白费】，而且白费的功照样占 CPU。
function simSSI(txns){
  const st=txns.map(t=>({id:t.id,ops:t.ops,p:0,done:false,start:0,
    rs:new Set(t.ops.filter(o=>!o.write).map(o=>o.key)),
    ws:new Set(t.ops.filter(o=>o.write).map(o=>o.key))}));
  const hist=[];                                   // 已提交事务的 {rs, ws}
  let tick=0,aborts=0,wasted=0,work=0;
  while(st.some(s=>!s.done)&&tick<8000){
    tick++;
    let budget=PAR;
    for(const s of st){
      if(s.done||budget<=0) continue;
      s.p++; work++; budget--;
      if(s.p<s.ops.length) continue;
      let conflict=false;
      for(let i=s.start;i<hist.length&&!conflict;i++){
        const u=hist[i];
        if(inter(s.ws,u.ws)) conflict=true;                       // ① 写-写
        else if(inter(s.rs,u.ws)&&inter(s.ws,u.rs)) conflict=true; // ② 双向 rw 反依赖
      }
      if(conflict){ aborts++; wasted+=s.ops.length; s.p=0; s.start=hist.length; }
      else { s.done=true; hist.push({rs:s.rs,ws:s.ws}); }
    }
  }
  return {tick,aborts,wasted,work,tput:txns.length/Math.max(tick,1)*100};
}
